class Item:
    def __init__(self, name: str, quantity: int, price: float):
        self.name = name
        self.quantity = quantity
        self.price = price

class Order:
    def __init__(self):
        self.items = []
        self.status = 'open'

    def add_item(self, item: Item) -> None:
        self.items.append(item)
